// static
bool StructTraits<::crosapi::mojom::NigoriKey::DataView, ::crosapi::mojom::NigoriKeyPtr>::Read(
    ::crosapi::mojom::NigoriKey::DataView input,
    ::crosapi::mojom::NigoriKeyPtr* output) {
  bool success = true;
  ::crosapi::mojom::NigoriKeyPtr result(::crosapi::mojom::NigoriKey::New());
  
      if (success && !input.ReadEncryptionKey(&result->encryption_key))
        success = false;
      if (success && !input.ReadMacKey(&result->mac_key))
        success = false;
  *output = std::move(result);
  return success;
}

